parameters.text:
={{ 
  $json.output    
    // Headings: #, ##, ###... → *Heading*
    .replace(/^#{1,6} (.*)$/gm, "*$1*")     

    // Bold: **bold** → *bold*
    .replace(/\*\*(.*?)\*\*/g, "*$1*")     

    // Italics: *italic* or _italic_ → _italic_
    .replace(/(^|[^*])\*(?!\s)([^*]+?)\*(?!\s)/g, "$1_$2_")  
    .replace(/_(.*?)_/g, "_$1_")     

    // Inline code: `code` → `code`
    .replace(/`([^`]+)`/g, "`$1`")     

    // Code block: ```...``` → ```...```
    .replace(/```([\s\S]*?)```/g, "```\n$1\n```")     

    // Links: [text](url) → <url|text>
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, "<$2|$1>")     

    // Bullets: - item or * item → • item
    .replace(/^- (.*)$/gm, "• $1")    
    .replace(/^\* (.*)$/gm, "• $1")     

    // Convert escaped \n to actual newlines
    .replace(/\\n/g, "\n")

    // TABLES: Convert Markdown tables to Slack-style code block tables
    .replace(/((?:\|.*\|(?:\n|$))+)/g, function(match) {
        let rows = match.trim().split("\n");
        rows = rows.map(r => r.trim().replace(/^\||\|$/g, "").split("|").map(c => c.trim()));

        // Calculate column widths
        let colWidths = [];
        rows.forEach(r => r.forEach((c,i) => {
            colWidths[i] = Math.max(colWidths[i] || 0, c.length);
        }));

        // Pad cells
        let formatted = rows.map(r => 
            r.map((c,i) => c.padEnd(colWidths[i], " ")).join(" | ")
        );

        return "```\n" + formatted.join("\n") + "\n```";
    })
}}

