={{ $json.output
    // Bold: **bold** → *bold*
    .replace(/\*\*(.*?)\*\*/g, "*$1*")
    // Italics: *italic* → _italic_
    .replace(/(^|[^*])\*(?!\s)([^*]+?)\*(?!\s)/g, "$1_$2_")
    // Strikethrough: ~~text~~ → ~text~
    .replace(/~~(.*?)~~/g, "~$1~")
    // Inline code: `code` → `code`
    .replace(/`([^`]+)`/g, "`$1`")
    // Code block passthrough to preserve
    .replace(/```([\s\S]*?)```/g, "```\n$1\n```")
    // Bullets: - item or * item → • item
    .replace(/^- (.*)$/gm, "• $1")
    .replace(/^\* (.*)$/gm, "• $1")
    // Convert escaped \n to actual newlines
    .replace(/\\n/g, "\n")
    // Tables: Convert Markdown table into monospaced block for alignment
    .replace(/((?:\|.*\|\n)+)/g, (match) => {
        const rows = match.trim().split("\n").map(r =>
            r.replace(/^\||\|$/g, "").split("|").map(c => c.trim())
        );
        const colWidths = rows[0].map((_, i) =>
            Math.max(...rows.map(r => (r[i] || "").length))
        );
        const formatted = rows.map(r =>
            r.map((c, i) => c.padEnd(colWidths[i])).join("   ")
        );
        return "```\n" + formatted.join("\n") + "\n```";
    })
}}
